package com.turboio.androidtests;
import android.app.*;import android.content.*;import android.database.Cursor;import android.net.Uri;import android.os.*;import android.provider.MediaStore;import android.view.*;import android.widget.*;import java.io.*;import java.lang.reflect.*;import java.nio.charset.StandardCharsets;import java.util.*;
/** Synthetic exports and gestures only. Never exports or deletes user material. */
public final class MaterialReadingProbe extends Instrumentation {
 private String nonce;private int checks;private void check(boolean ok){checks++;if(!ok)throw new AssertionError("READING_PROBE_CHECK_"+checks);}
 public void onCreate(Bundle args){super.onCreate(args);nonce=args.getString("probe_id","");start();}
 private List<Uri> files(Context app,String prefix)throws Exception{List<Uri> result=new ArrayList<>();try(Cursor c=app.getContentResolver().query(MediaStore.Downloads.EXTERNAL_CONTENT_URI,new String[]{"_id"},"_display_name LIKE ?",new String[]{prefix+"%"},null)){while(c!=null&&c.moveToNext())result.add(ContentUris.withAppendedId(MediaStore.Downloads.EXTERNAL_CONTENT_URI,c.getLong(0)));}return result;}
 public void onStart(){Bundle report=new Bundle();Context app=getTargetContext();String prefix="io-material-selftest-"+nonce;List<Uri> created=new ArrayList<>();try{check(nonce.matches("[a-f0-9]{32}"));ClassLoader loader=app.getClassLoader();Context isolated=new ContextWrapper(app){public SharedPreferences getSharedPreferences(String name,int mode){return app.getSharedPreferences("io-material-selftest-"+nonce,mode);}};
  Class<?> type=loader.loadClass("com.turboio.addon.ExportDestination"),writer=loader.loadClass("com.turboio.addon.ExportDestination$Writer");Method write=type.getDeclaredMethod("write",Context.class,String.class,String.class,writer);write.setAccessible(true);Object payload=Proxy.newProxyInstance(loader,new Class<?>[]{writer},(p,m,v)->{((OutputStream)v[0]).write("synthetic export".getBytes(StandardCharsets.UTF_8));return null;});
  check(files(app,prefix).isEmpty());String first=(String)write.invoke(null,isolated,prefix+".txt","text/plain",payload),second=(String)write.invoke(null,isolated,prefix+".txt","text/plain",payload);created=files(app,prefix);check(created.size()==2);check(!first.equals(second));for(Uri uri:created){try(Cursor c=app.getContentResolver().query(uri,new String[]{"relative_path","is_pending"},null,null,null)){check(c!=null&&c.moveToFirst()&&"Download/IO 文档/".equals(c.getString(0))&&c.getInt(1)==0);}try(InputStream in=app.getContentResolver().openInputStream(uri)){byte[] bytes=new byte[64];int n=in.read(bytes);check("synthetic export".equals(new String(bytes,0,n,StandardCharsets.UTF_8)));}}
  Object fail=Proxy.newProxyInstance(loader,new Class<?>[]{writer},(p,m,v)->{((OutputStream)v[0]).write(1);throw new IOException("SYNTHETIC_WRITE_FAILURE");});boolean rejected=false;try{write.invoke(null,isolated,prefix+"-failed.txt","text/plain",fail);}catch(InvocationTargetException expected){rejected=true;}check(rejected);check(files(app,prefix).size()==2);
  Activity activity=startActivitySync(new Intent().setClassName(app,"com.rayneo.venus.MainActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Throwable[] problem={null};runOnMainSync(()->{try{Class<?> rowType=loader.loadClass("com.turboio.addon.MaterialActionsRow"),openedType=loader.loadClass("com.turboio.addon.MaterialActionsRow$Opened");Constructor<?> ctor=rowType.getDeclaredConstructor(Activity.class,View.class,openedType);ctor.setAccessible(true);TextView content=new TextView(activity);content.setText("Synthetic gesture row");content.setOnClickListener(v->{});ViewGroup row=(ViewGroup)ctor.newInstance(activity,content,Proxy.newProxyInstance(loader,new Class<?>[]{openedType},(p,m,v)->null));FrameLayout parent=new FrameLayout(activity);parent.addView(row);row.measure(View.MeasureSpec.makeMeasureSpec(900,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(200,View.MeasureSpec.EXACTLY));row.layout(0,0,900,200);long t=SystemClock.uptimeMillis();send(row,t,0,10,10);send(row,t,2,220,12);send(row,t,2,230,12);check(content.getTranslationX()>0);send(row,t,3,220,12);check(content.getTranslationX()==0);send(row,t+10,0,10,10);send(row,t+10,2,12,100);send(row,t+10,2,250,12);check(content.getTranslationX()==0);send(row,t+10,3,250,12);}catch(Throwable e){problem[0]=e;}});if(problem[0]!=null)throw problem[0];
  report.putInt("checks",checks);report.putBoolean("default_folder_and_no_overwrite",true);report.putBoolean("failed_export_cleaned",true);report.putBoolean("horizontal_vertical_direction_lock",true);report.putBoolean("user_files_or_network_accessed",false);report.putBoolean("passed",true);
 }catch(Throwable e){while(e.getCause()!=null)e=e.getCause();report.putString("error",e.getMessage()!=null&&e.getMessage().matches("[A-Z_0-9]{3,100}")?e.getMessage():e.getClass().getSimpleName());report.putBoolean("passed",false);}finally{try{for(Uri uri:files(app,prefix))app.getContentResolver().delete(uri,null,null);app.deleteSharedPreferences("io-material-selftest-"+nonce);report.putBoolean("synthetic_files_removed",files(app,prefix).isEmpty());}catch(Exception e){report.putBoolean("synthetic_files_removed",false);}finish(Activity.RESULT_OK,report);}}
 private static void send(View row,long time,int action,float x,float y){MotionEvent e=MotionEvent.obtain(time,time+16,action,x,y,0);try{row.dispatchTouchEvent(e);}finally{e.recycle();}}
}
